// Кейс: .qa/tests/devices/DEV-011.md · план: .qa/e2e-app/specs/app.md (1.34)
// Только просмотр: окно удаления открывается и закрывается «ביטול». «הסרה» НЕ нажимается.
import { by, assert, skip } from '../../lib/appium.mjs';
import { openDevices, SECOND } from './devices-helpers.mjs';

export const name = '«מכשירים» → второй телефон → «הסרת הטלפון מהחשבון»: «הטלפון ייצא מהחשבון», возврат только по QR, без «אפשר לחבר אותו שוב בכל רגע» → «ביטול» #272dc6 @iphone @app @prod-safe';

export default async function (app) {
  // 1. «חשבון» → «מכשירים» → строка «מכשיר נוסף».
  await openDevices(app);
  if (!(await app.exists(SECOND))) {
    await app.scrollTo(SECOND, { max: 3, what: 'строка «מכשיר נוסף»' }).catch(() => null);
    if (!(await app.exists(SECOND))) skip('в аккаунте нет дополнительного телефона — подключить второй по QR (DEV-012 шаги 5–7)');
  }
  await (await app.waitFor(SECOND, { what: 'строка «מכשיר נוסף»' })).click();

  // 2. Шторка роли → «הסרת הטלפון מהחשבון».
  await app.tap(by.exact('הסרת הטלפון מהחשבון'), { what: '«הסרת הטלפון מהחשבון» в шторке телефона' });

  // 3. Окно удаления: тексты по «מה רצוי» #272dc6 и проверке 03.11.
  const title = await app.waitFor(by.begins('להסיר את'), { what: 'заголовок «להסיר את <имя>?»' });
  const t = String((await title.attr('label').catch(() => '')) || (await title.attr('name')));
  console.log(`     заголовок: «${t}»`);
  assert(/^להסיר את .+\?$/.test(t.trim()), `заголовок вида «להסיר את <имя>?» (сейчас «${t}»)`);
  await app.waitFor(by.contains('הטלפון ייצא מהחשבון'), { what: '«הטלפון ייצא מהחשבון.»' });
  await app.waitFor(by.contains('הטלפון לא יקבל התרעות'), { what: '«הטלפון לא יקבל התרעות»' });
  await app.waitFor(by.contains('הוא יוסר מרשימת הטלפונים'), { what: '«הוא יוסר מרשימת הטלפונים»' });
  await app.waitFor(by.contains('סורקים בו קוד QR מהטלפון הראשי'), { what: '«כדי לחבר אותו שוב, סורקים בו קוד QR מהטלפון הראשי.»' });
  await app.waitFor(by.exact('הסרה'), { what: 'кнопка «הסרה»' });
  assert(!(await app.exists(by.contains('אפשר לחבר אותו שוב בכל רגע'))), 'нет старого обещания «אפשר לחבר אותו שוב בכל רגע»');
  assert(!(await app.exists(by.contains('הטלפון ינותק מהחשבון'))), 'нет старого «הטלפון ינותק מהחשבון»');
  await app.screenshot('272dc6-auto-remove-confirm');

  // 4. «ביטול» → окно закрыто, телефон не удалён.
  await app.tap(by.exact('ביטול'), { what: 'кнопка «ביטול»' });
  await app.waitGone(by.begins('להסיר את'), { what: 'окно «להסיר את …?»' });
  await app.restart();
  await openDevices(app);
  await app.waitFor(SECOND, { what: 'второй телефон в списке после «ביטול» (не удалён)' });
  await app.restart();
}
